import {CubeLinkUSB,hardwareStatus,INITIALIZED} from './hardware.js';
import {PhysicalRunner} from './hardware-runner.js';
import {LIMITS} from './core.js';
export function mountHardware({program,highlight,lock,status,beginPhysical,onPose,onSensor}){
 const $=id=>document.getElementById(id);let busy=false,physical=false,lastState='disconnected';const lines=[];
 const usb=new CubeLinkUSB({onChange:()=>{render();if(!usb.ready&&physicalRunner?.running)physicalRunner.cancel();},onLine:line=>{lines.push(line);if(lines.length>80)lines.shift();$('hw-log').textContent=lines.join('\n');}});
 const physicalRunner=new PhysicalRunner(usb,{onStep:highlight,onPose,onSensor});
 function render(){const state=usb.state,connected=state!=='disconnected';if(state!==lastState&&['verified','recovery'].includes(state)){const pose=lastState==='verifying'?usb.reportedPose:usb.pose;for(const k of Object.keys(LIMITS))if(Number.isFinite(pose?.[k]))$('hw-start-'+k).value=pose[k];}lastState=state;$('hw-status').textContent=usb.message||'USB 연결 전';$('hw-state').textContent=({disconnected:'연결 전',opening:'포트 선택',verifying:'펌웨어 확인',verified:usb.identity?.safeInit?'정상 연결 · 준비 전':'호환 모드 연결',recovery:'자세 확인 필요',initializing:'초기화 중',ready:usb.autoInitialized?'실물 준비 완료':'호환 모드 준비',stopping:'모터 해제 중',parking:'저장 종료 중',fault:'연결 오류'})[state];
  const automatic=!!usb.identity?.safeInit&&$('hw-power').value==='auto';$('hw-confirm-label').textContent=automatic?'전원을 끈 상태에서 저장자세 90° / 30° / 160° / 90°를 맞추고 팔을 받쳤습니다.':'현재 로봇 자세와 아래 시작각도를 확인했습니다. 자동 초기화 없이 한 축씩 점검합니다.';$('hw-start-pose').hidden=automatic;$('hw-init').textContent=automatic?'확인한 저장자세에서 초기화':'현재 자세 확인 · 호환 제어 준비';$('hw-firmware').textContent=usb.identity?(usb.identity.firmware+' · '+(usb.identity.mode==='protocol2'?'Protocol 2':'Legacy')+(usb.identity.safeInit?' · 안전 초기화 지원':' · 수동 호환 모드')):'연결 후 자동 표시';$('hw-capabilities').textContent=usb.identity?(usb.identity.stop?'모터 해제 지원 확인':'명령 전송 정지만 가능 · 모터 전원은 유지됩니다.'):'지원 기능은 연결 후 확인합니다.';$('hw-emergency').textContent=usb.identity?.stop?'■ 모터 해제':'■ 전송 정지';
  $('hw-connect').disabled=connected||busy||!usb.serial;$('hw-power').disabled=busy||usb.ready;$('hw-init').disabled=busy||!['verified','recovery'].includes(state)||!$('hw-confirm').checked;$('hw-disconnect').disabled=!connected||busy;$('hw-park').disabled=!usb.ready||!usb.canPark||busy;$('hw-manual').disabled=!usb.ready||busy;$('hw-teach').disabled=!usb.ready||busy;$('real-run').disabled=!usb.ready||busy||!$('hw-trial').checked;$('hw-emergency').disabled=!usb.identity||!usb.writer;
  $('hw-distance').textContent=usb.distance===null?'미수신':usb.distance+' cm'+(Date.now()-usb.distanceAt>1500?' (오래된 값)':'');$('hw-pose').textContent=Object.values(usb.pose).join('° / ')+'°';$('hw-taught').textContent=[...usb.teach.keys()].join(', ')||'저장한 작업대 위치 없음';
  if(!['initializing','verified','recovery'].includes(state))$('hw-confirm').checked=false;
 }
 function setBusy(value){busy=value;lock(value);render();}
 async function action(fn){if(busy)return;setBusy(true);try{await fn();}catch(e){status(e.message);$('hw-status').textContent=e.message;}finally{setBusy(false);}}
 $('hardware').textContent='USB 실물 연결';$('hardware').onclick=()=>{$('hardware-dialog').showModal();render();};
 $('hw-connect').onclick=()=>action(async()=>{await usb.connect();for(const k of Object.keys(LIMITS))$('hw-start-'+k).value=usb.reportedPose[k]??90;render();});$('hw-init').onclick=()=>action(async()=>{const pose=Object.fromEntries(Object.keys(LIMITS).map(k=>[k,Number($('hw-start-'+k).value)]));await usb.initialize($('hw-confirm').checked,{powerMode:$('hw-power').value,pose});onPose({...usb.pose});status(usb.message);});
 $('hw-power').onchange=()=>{$('hw-confirm').checked=false;render();};$('hw-confirm').onchange=render;$('hw-trial').onchange=render;$('hw-disconnect').onclick=()=>action(async()=>{await usb.close();status(usb.message);});$('hw-park').onclick=()=>action(async()=>{await usb.park();onPose({...usb.pose});status('저장자세 이동·모터 해제 완료');});
 $('hw-emergency').onclick=async()=>{physicalRunner.cancel();try{await usb.emergency();status(usb.message);}catch(e){status(e.message);}render();};
 function range(){const k=$('hw-joint').value,[lo,hi]=LIMITS[k];$('hw-angle').min=lo;$('hw-angle').max=hi;$('hw-angle').value=usb.pose[k];$('hw-range').textContent=lo+'~'+hi+'°';}range();$('hw-joint').onchange=range;
 $('hw-manual').onclick=()=>action(async()=>{physical=true;try{beginPhysical();await usb.moveTo({...usb.pose,[$('hw-joint').value]:Number($('hw-angle').value)},{onPose});status('선택한 관절의 명령 전송 완료 · 실제 방향을 확인하세요.');}finally{physical=false;}});
 $('hw-teach').onclick=()=>{try{usb.record($('hw-station').value,$('hw-level').value);status('현재 명령 자세를 작업대 위치로 저장했습니다.');}catch(e){status(e.message);}render();};
 $('real-run').onclick=()=>action(async()=>{if(!$('hw-trial').checked)throw Error('실물 시험판 안내를 먼저 확인하세요.');const p=program();physical=true;beginPhysical();status('실물 실행 중 · 큐브 성공 여부는 관찰로 확인하세요.');try{const done=await physicalRunner.run(p);status(done?'실물 명령 전송 완료 · 가상 점수를 자동 부여하지 않습니다.':'실물 실행을 정지했습니다.');}catch(e){await usb.emergency().catch(()=>{});throw e;}finally{physical=false;highlight(null);}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&physicalRunner.running){physicalRunner.cancel();usb.emergency().catch(()=>{});}});
 window.addEventListener('beforeunload',e=>{if(usb.ready||physicalRunner.running){e.preventDefault();e.returnValue='';}});
 $('hw-notice').textContent=hardwareStatus.reason+(usb.serial?'':' 이 브라우저에서는 USB 시리얼을 사용할 수 없습니다. PC Chrome/Edge로 열어주세요.');render();
 return {usb,lock(value){busy=value;render();},isPhysical:()=>physical||['initializing','parking'].includes(usb.state),stop:async()=>{physicalRunner.cancel();await usb.emergency();return usb.message;},hasMotor:()=>usb.ready,INITIALIZED};
}
